        // ARCHITECTURE: See docs/design/ARCHITECTURE.md for Version Management, Status Icons, Cache-Busting patterns
        const { useState, useEffect, useLayoutEffect, useRef, useMemo } = React;

        // ===== Overlay system — the React half (v7.18.0; docs/design/DIALOG-DISMISSAL-AUDIT.md) =====
        // The ordered stack lives in overlayRegistry.js (pure, Node-tested — global `overlayRegistry`).
        // An overlay built with <Dialog> self-registers on mount / deregisters on unmount, so the
        // keystroke fence (hasFence()), Esc-ordering, backdrop, ✕, and cascade-close are STRUCTURAL —
        // it cannot be born unfenced/un-Esc-able/un-dismissable. Migrating outward-in, one family per
        // alpha. As of alpha.43 the legacy anyDialogOpen OR-chain + handleModalEsc are gone (every modal migrated);
        // remaining legacy overlays: the book/folder/sort context menus, anchored dropdowns, imperative dialogs.
        //
        // useOverlayLayer: registers { close, kind } for this overlay's lifetime. `close` is read through
        // a ref so the registry always calls the LATEST onClose without re-registering each render.
        // fence (optional, v7.18.0-alpha.40): raise the keystroke fence. Undefined = the registry default
        // (modal + menu fence, popover doesn't — alpha.44); a popover passes true to block library keys while open.
        // idRef (optional, alpha.45): receives this layer's registry id, so a <Popover> can ask "am I topmost?".
        // selectAll (optional, v7.19.0): the overlay's own Ctrl+A action (read via ref = always the latest closure).
        const useOverlayLayer = ({ close, kind, nodeRef, fence, idRef, selectAll }) => {
            const closeRef = useRef(close);
            closeRef.current = close;
            const selectAllRef = useRef(selectAll);
            selectAllRef.current = selectAll;
            const [isTopModal, setIsTopModal] = useState(true);
            // useLayoutEffect (not useEffect): push/subscribe + the isTopModal recompute must run BEFORE paint,
            // so when a modal opens/closes the layer beneath flips its dim in the SAME frame — no one-frame
            // double-dim flash (the reason we don't need a separate global "already dimmed" flag).
            useLayoutEffect(() => {
                const id = overlayRegistry.pushLayer({ close: (reason) => closeRef.current && closeRef.current(reason), kind, nodeRef, fence,
                    // selectAll is a function (one checklist) or { key: fn } (several — the area's data-select-items names which)
                    selectAll: (key) => {
                        const sa = selectAllRef.current;
                        const fn = typeof sa === 'function' ? sa : (sa && sa[key]);
                        if (!fn) return false;
                        fn(); return true;
                    } });
                if (idRef) idRef.current = id;
                const sync = () => setIsTopModal(overlayRegistry.isTopmostModal(id));
                sync();
                const unsub = overlayRegistry.subscribe(sync); // recompute when anything opens/closes above us
                return () => { unsub(); overlayRegistry.removeLayer(id); };
            }, [kind]); // mount/unmount only — kind is fixed for a given overlay
            return isTopModal; // <Dialog> dims its scrim ONLY when topmost modal, so stacked scrims don't compound
        };

        // <Dialog> — a modal overlay. Portals to <body> (escapes ancestor z-index/overflow traps),
        // renders a scrim with a mousedown-guarded backdrop close (a drag that STARTED inside the panel
        // and released on the scrim does NOT dismiss), a baked-in ✕, an optional titled header, and
        // children. kind:'modal' means it raises the keystroke fence (a modal layer fences by default → hasFence()).
        // Optional props for the varied existing dialogs (all backward-compatible):
        //   panelClassName — full override of the panel's classes (else bg-white rounded-lg shadow-2xl <maxW> w-full mx-4)
        //   panelStyle     — inline style on the panel (e.g. a fixed max-width / max-height + flex column for a scroll body)
        //   zIndexClass    — scrim z-index class (default z-50; high-priority notices use z-[100])
        //   showClose/title — omit both to supply a fully custom header as children
        //   closeButton    — render a standard corner ✕ (for custom-header dialogs); auto-adds `relative` to the panel
        // Ctrl+A (v7.19.0, Ron + UX) — acts on the AREA of the window you last clicked in / Tabbed to, never "the whole panel":
        //   data-select-text        — mark a text area (a title, a paragraph): Ctrl+A selects just that text;
        //   data-select-items="key" — mark a checklist area: Ctrl+A runs selectAll (a function, or { key: fn } when the
        //                             window has several lists) — checks every item in THAT list (= its Select all);
        //   data-dialog-body        — the main text used when nothing in the window has been clicked yet.
        //   See the dialogUp() Ctrl+A branch in the keydown handler.
        const Dialog = ({ onClose, title, children, panelClassName, maxWidthClassName = 'max-w-sm', showClose = true, zIndexClass = 'z-50', panelStyle, closeButton = false, selectAll }) => {
            const panelRef = useRef(null);
            const isTopModal = useOverlayLayer({ close: onClose, kind: 'modal', nodeRef: panelRef, selectAll });
            const downOnScrimRef = useRef(false);
            const _panelCls = (panelClassName || `bg-white rounded-lg shadow-2xl ${maxWidthClassName} w-full mx-4`) + (closeButton ? ' relative' : '');
            return ReactDOM.createPortal(
                // Dim only when this is the topmost modal — a modal beneath another goes transparent so
                // stacked backdrops don't compound to near-black (popovers above don't count as modals).
                <div className={`fixed inset-0 ${isTopModal ? 'bg-black bg-opacity-50' : 'bg-transparent'} flex items-center justify-center ${zIndexClass}`}
                    onMouseDown={(e) => { downOnScrimRef.current = (e.target === e.currentTarget); }}
                    onClick={(e) => { if (e.target === e.currentTarget && downOnScrimRef.current && onClose) onClose('backdrop'); downOnScrimRef.current = false; }}>
                    <div ref={panelRef} className={_panelCls}
                        style={panelStyle} role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
                        {closeButton && <button onClick={() => onClose && onClose('button')} className="absolute top-3 right-3 text-gray-400 hover:text-gray-700 text-xl leading-none z-10" title="Close" aria-label="Close">×</button>}
                        {(title || showClose) && (
                            <div className="flex justify-between items-start p-4 border-b border-gray-200">
                                {title ? <h2 data-select-text className="text-base font-semibold text-gray-900">{title}</h2> : <span />}
                                {showClose && <button onClick={() => onClose && onClose('button')} className="text-gray-400 hover:text-gray-600 text-xl font-bold leading-none" title="Close" aria-label="Close">×</button>}
                            </div>
                        )}
                        {children}
                    </div>
                </div>,
                document.body
            );
        };

        // v7.19.0-alpha.4 (Ron + UX) - THE "Select all / Clear" link in a checklist SECTION's header: one piece for every
        // section (removed-books groups, Tag from Collections' books pane + "Removed from Kindle"), so they can't drift.
        // Reads "Clear" when every item in the section is checked, else "Select all". Ctrl+A in the section does the
        // same select-all (data-select-items + <Dialog selectAll>).
        const SelectAllToggle = ({ allChecked, onToggle }) => (
            <button type="button" onClick={onToggle} className="text-xs text-blue-600 hover:underline flex-shrink-0 ml-2">
                {allChecked ? 'Clear' : 'Select all'}
            </button>
        );

        // v7.20.0-alpha.2 (Ron) - THE menu-bar item + divider (File / View / Tools / Help). Each item used to carry ~6 lines
        // of hand-copied inline style + two JS hover handlers (~15 copies); the look now lives in readerwrangler.css
        // (.rw-menu-item — hover is a CSS rule). Options: disabled, danger (red, e.g. Reset App), checked (true/false
        // draws View's ✓ column; omit for plain items), style (the two odd ones: Relay Setup's icon, Theme's ▶).
        const MenuBarItem = ({ onClick, disabled, title, danger, checked, style, children }) => (
            <button type="button" onClick={onClick} disabled={disabled} title={title || undefined} style={style}
                className={`rw-menu-item${danger ? ' rw-menu-item--danger' : ''}${checked !== undefined ? ' rw-menu-item--check' : ''}`}>
                {checked && <span className="rw-menu-item__check">✓</span>}
                {children}
            </button>
        );
        const MenuDivider = () => <div className="rw-menu-divider" />;

        // APP_VERSION - Defined ONCE in readerwrangler.html, available in global scope
        // Single source of truth - no duplication!

        // Clear emergency reset timer — app code loaded successfully
        if (window._appMountTimer) { clearTimeout(window._appMountTimer); window._appMountTimer = null; }

        const ORGANIZER_VERSION = "7.26.0-alpha.25";  // Build version for this file
        // 7.26.0 - the code's own build, once it runs: the page-load entry can't know it (it's written before this code is
        // compiled) and the page's APP_VERSION doesn't move during alphas
        rwLog.log('info', 'BOOT', `Desktop app ${ORGANIZER_VERSION} running (page ${APP_VERSION})`);

        // v6.19.0 - Dev environments talk to the DEV relay worker (isolated KV namespace), so
        // local/dev testing can never touch production relay data. Mirrors the nav-hub's rule,
        // so a DEV bookmarklet and a localhost app share the same (dev) relay universe.
        // Escape hatch: run  window._RW_RELAY_WORKER_URL = ''  in the console (then re-import)
        // to point a dev app at the production worker deliberately.
        // v7.21.0 - CONTRIBUTOR-based, not "localhost": a self-hoster (local server, no contributor flag) reads the
        // PRODUCTION relay like any user — they used to land on the dev relay. Asks the environment answers defined once in
        // readerwrangler.html (isContributor / isDevSite); the dev site keeps the dev relay as before.
        (() => {
            if ((isContributor() || isDevSite()) && window._RW_RELAY_WORKER_URL === undefined) {
                window._RW_RELAY_WORKER_URL = 'https://readerwrangler-relay-dev.readerwrangler.workers.dev';
                rwLog.log('info', 'BOOT', `This copy uses the dev relay (${window._RW_RELAY_WORKER_URL})`);
            }
        })();

        // v7.13.2 - The hidden var made visible: which relay worker+storage this build reads.
        // Dev/localhost share the dev worker+storage; prod reads prod. Surfaced on Relay Setup and
        // Data Status (dev builds only — a prod user needs no "prod relay" jargon) so the data's true
        // address is (worker × channel), both visible, never a silent split (Law 16).
        const RELAY_IS_DEV = typeof window !== 'undefined' && !!window._RW_RELAY_WORKER_URL && window._RW_RELAY_WORKER_URL.includes('-dev');

        // v5.0.0-alpha.172.1 - Static column configuration (outside component for performance)
        const COLUMN_CONFIG = {
            title: { label: 'Name', sortKey: 'title', defaultDir: 'asc', cssVar: '--col-title', alwaysVisible: true },
            author: { label: 'Author', sortKey: 'author', defaultDir: 'asc', cssVar: '--col-author' },
            series: { label: 'Series', sortKey: 'series', defaultDir: 'asc', cssVar: '--col-series' },
            seriesNum: { label: '#', sortKey: 'seriesNum', defaultDir: 'asc', cssVar: '--col-seriesNum', textCenter: true },
            rating: { label: 'Rating', sortKey: 'rating', defaultDir: 'asc', cssVar: '--col-rating' },
            myRating: { label: 'My Rating', sortKey: 'myRating', defaultDir: 'desc', cssVar: '--col-myRating' },
            dateAdded: { label: 'Date Added', sortKey: 'dateAdded', defaultDir: 'desc', cssVar: '--col-dateAdded' },
            publicationDate: { label: 'Published', sortKey: 'publicationDate', defaultDir: 'asc', cssVar: '--col-publicationDate' }, // v6.16.0 - chronological/series order
            price: { label: 'Price', sortKey: 'price', defaultDir: 'asc', cssVar: '--col-price' },
            priceGoal: { label: 'Goal', sortKey: 'priceGoal', defaultDir: 'asc', cssVar: '--col-priceGoal' },
            priceWhenSet: { label: 'Price When Set', sortKey: 'priceWhenSet', defaultDir: 'asc', cssVar: '--col-priceWhenSet' }, // v7.12.0 - snapshot at goal-set time
            delta: { label: 'Under', sortKey: 'delta', defaultDir: 'desc', cssVar: '--col-delta' },
            ownership: { label: 'Ownership', sortKey: 'ownership', defaultDir: 'asc', cssVar: '--col-ownership' }, // v6.12.0
            format: { label: 'Format', sortKey: 'format', defaultDir: 'asc', cssVar: '--col-format' }, // v6.12.0 - book.binding
            asin: { label: 'ASIN', sortKey: 'asin', defaultDir: 'asc', cssVar: '--col-asin' }, // v6.12.0
            amazon: { label: 'Amazon', sortKey: null, cssVar: '--col-amazon', textCenter: true, noResize: true }
        };

        // v7.1.0 - Price staleness. Sale prices can turn in a day, so a price older than this
        // renders dimmed with an "as of" tooltip — honest about what we actually know. Global
        // constant by design; promote to a user setting only if the default proves annoying.
        const PRICE_STALE_MS = 24 * 60 * 60 * 1000;
        const priceIsStale = (book) =>
            !book.priceFetchedAt || (Date.now() - new Date(book.priceFetchedAt).getTime()) > PRICE_STALE_MS;
        const priceAsOfLabel = (book) => book.priceFetchedAt
            ? `Price as of ${new Date(book.priceFetchedAt).toLocaleString()}`
            : 'Price from an older fetch (date unknown)';

        // v6.12.0 - Single source of truth for acquisition/ownership type (label + dialog badge color).
        // Cover view keeps its own short labels (KU/COMIX) for the tiny tile badge.
        const OWNERSHIP_META = {
            purchased:       { label: 'Owned',            badge: null },          // no badge (common case); data key 'purchased' unchanged
            sample:          { label: 'Sample',           badge: 'bg-amber-500' },
            wishlist:        { label: 'Wishlist',         badge: 'bg-pink-600' },
            borrowed:        { label: 'Borrowed',         badge: 'bg-teal-500' },
            prime:           { label: 'Prime',            badge: 'bg-purple-500' },
            kindleUnlimited: { label: 'Kindle Unlimited', badge: 'bg-purple-500' },
            koll:            { label: 'KOLL',             badge: 'bg-purple-500' },
            comixology:      { label: 'Comixology',       badge: 'bg-purple-500' },
            insideAmazon:    { label: 'Insider',          badge: 'bg-purple-500' },
            // v7.7.0-alpha.4 - Both arrived via fetcher newOwnershipType telemetry (2026-09-03);
            // classified by fetcher v5.2.0. Library loans wear borrow teal; Audible Plus wears
            // subscription purple (the KU/Prime family).
            publicLibraryLending: { label: 'Library Loan', badge: 'bg-teal-500' },
            audiblePlus:     { label: 'Audible Plus',     badge: 'bg-purple-500' },
            unknown:         { label: 'Unknown',          badge: 'bg-gray-500' }
        };
        // v7.8.0 (item 0) - wishlist truth = isWishlisted() (uiHelpers.js); the flag is wire baggage.
        const getOwnershipType = (book) =>
            isWishlisted(book) ? 'wishlist' : (book.ownershipType || 'purchased');
        const getOwnershipLabel = (book) => (OWNERSHIP_META[getOwnershipType(book)] || OWNERSHIP_META.unknown).label;
        // v7.19.0 - THE "no longer in your Amazon library" state of a book (docs/design/ORPHAN-CLEANUP.md §2), derived
        // from two fields with DIFFERENT owners — orphanStatus (the fetcher's scan; sticky by freshness) and
        // isKeptOrphan (the user's Keep; user-owned, so no fetch can un-keep). Callers read THIS, never the raw pair:
        //   'none'    — in your Amazon library (or never scanned)
        //   'review'  — gone from Amazon, still filed in RW, not yet decided → the review window + reminder
        //   'kept'    — gone from Amazon, you chose Keep → never asked again
        //   'trashed' — gone from Amazon and already in your Trash (your own decision) → finalize-only
        const amazonRemovalState = (book) => {
            if (!book || book.orphanStatus !== 'orphan') return 'none';
            if (book.isDeleted) return 'trashed';
            return book.isKeptOrphan ? 'kept' : 'review';
        };
        // v7.4.0 - Badge local instances (tab title + header chip): two identical-looking tabs,
        // one production and one localhost, is how restores land on the wrong instance. Subtle
        // by intent — users legitimately run local clones; this is a label, not a warning.
        // v7.21.0 - asks the environment answers (readerwrangler.html): any LOCAL SERVER gets the label (home network too);
        // a CONTRIBUTOR's label says so — the contributor-mode fail-safe (spec): impossible to miss, no pop-ups.
        const IS_LOCAL_HOST = isLocalServer();
        const IS_CONTRIBUTOR = isContributor();
        document.title = IS_CONTRIBUTOR ? "ReaderWrangler (local · contributor)" : IS_LOCAL_HOST ? "ReaderWrangler (local)" : "ReaderWrangler";
        // Constants and helper functions moved to uiHelpers.js and storage.js (v5.0.0)
        // saveBooksToIndexedDB, loadBooksFromIndexedDB, deleteBookStore, onBookStoreGone - see storage.js
        // normalizeBook, parsePrice, getAmazonUrl, calculateFreshness, formatRelativeTime - see uiHelpers.js
        // buildCoverUrlMap, populateCoverCache - see storage.js

        // v5.0.0-alpha.130: Reusable info dialog for large messages (avoids alert() scrollbar issues)
        // v5.5.7-alpha.13: CSS variables for dark mode support
        // v7.10.1-alpha.6 (DIALOG_POLICY, audit sweep B) - the imperative overlays (confirm/input/info/
        // choice/progress/delete-warning) live outside React, so the registry can't see them. DOM
        // detection instead of a counter: presence of the class IS the truth, nothing can drift.
        const imperativeDialogsUp = () => !!document.querySelector('.rw-imperative-overlay');

        // v7.10.1-alpha.9 (Ron) - shared dismissal chrome for the imperative dialogs: Esc cancels and
        // an ✕ in the corner closes (both yield the dialog's cancel value). Capture-phase listener so
        // the keystroke never reaches the app underneath (keystroke scope consistency); when dialogs
        // stack, only the TOPMOST overlay responds. showProgressDialog deliberately opts out (a running
        // import must not be Esc-dismissed). Every exit path must use the returned close() — it detaches
        // the listener exactly once and is idempotent.
        // v7.18.0-alpha.68 - the imperative dialogs are now LAYERS in the one overlay stack (overlayRegistry) instead of a
        // parallel system with its own Esc listener: registering on open gives them the shared innermost-first Esc (the
        // registry listener closes the TOP layer and consumes the key), the keystroke + undo fence (hasFence), Ctrl+A scoped
        // to the dialog's text (nodeRef), and correct stacking with React <Dialog>s/<Popover>s (a popup under one of these
        // ignores clicks — it isn't topmost). Their look is unchanged (Ron: keep them as they are; only how they close).
        function attachDialogDismiss(overlay, dialog, closeRaw, cancelValue) {
            let closed = false;
            let layerId = null;
            const close = (val) => {
                if (closed) return;
                closed = true;
                if (layerId != null) overlayRegistry.removeLayer(layerId);
                closeRaw(val);
            };
            // alpha.69 - detached: opened from a menu item, it sits ABOVE that menu; the menu closing must not take it along.
            layerId = overlayRegistry.pushLayer({ close: () => close(cancelValue), kind: 'modal', nodeRef: { current: dialog }, detached: true });
            const x = document.createElement('button');
            x.textContent = '✕';
            x.setAttribute('aria-label', 'Close');
            x.title = 'Close';
            x.style.cssText = 'position: absolute; top: 10px; right: 12px; background: none; border: none; font-size: 16px; line-height: 1; cursor: pointer; color: var(--text-muted); padding: 4px;';
            x.onmouseover = () => x.style.color = 'var(--text-primary)';
            x.onmouseout = () => x.style.color = 'var(--text-muted)';
            x.onclick = () => close(cancelValue);
            dialog.style.position = 'relative';
            dialog.appendChild(x);
            onBackdropClick(overlay, layerId, () => close(cancelValue));
            return close;
        }

        // v7.18.0-alpha.70 (Ron) - a click on the dimmed background closes an imperative dialog, as it does every React
        // <Dialog> (only "Name already in use" did, via its own handler). Same guard as <Dialog>: the press must START on
        // the background, so a text drag that ends outside the box doesn't close it; and only the TOPMOST layer reacts.
        function onBackdropClick(overlay, layerId, onBackdrop) {
            let downOnScrim = false;
            overlay.addEventListener('mousedown', (e) => { downOnScrim = e.target === overlay; });
            overlay.addEventListener('click', (e) => {
                const top = overlayRegistry.topLayer();
                if (e.target === overlay && downOnScrim && top && top.id === layerId) onBackdrop();
                downOnScrim = false;
            });
        }

        // v7.19.0-alpha.4 - Ctrl+A areas for the imperative boxes: title and message are separate text areas; the
        // message is the default when nothing's been clicked. (Button labels are never selectable — readerwrangler.css.)
        function markDialogText(titleEl, messageEl) {
            titleEl.setAttribute('data-select-text', '');
            messageEl.setAttribute('data-select-text', '');
            messageEl.setAttribute('data-dialog-body', '');
        }

        // 7.26.0 (Ron, 2026-11-09 — option 1) - Every dialog names its AREA first and logs what it showed there, and the
        // answer for those that ask (rwLog.dialog — the one logging call whose code isn't written literally; the commit
        // check verifies each call's area instead, tools/message_codes.py). The boxes themselves are unchanged, below.
        const dialogShown = (area, title, message) => rwLog.dialog(area, `Box shown: "${title}" — ${message}`);
        const dialogAnswered = (area, title, answer) => rwLog.dialog(area, `Box "${title}" answered: ${answer}`);
        function showInfoDialog(area, title, message) {
            dialogShown(area, title, message);
            return infoBox(title, message);
        }
        function showProgressDialog(area, title, message) {
            dialogShown(area, title, message);
            const box = progressBox(title, message);
            return {
                ...box,
                finish(newTitle, msg, extras) {
                    dialogShown(area, newTitle, msg);
                    return box.finish(newTitle, msg, extras).then((key) => {
                        if (key) dialogAnswered(area, newTitle, ((extras || []).find(x => x.key === key) || {}).label || key);
                        return key;
                    });
                }
            };
        }
        function showConfirmDialog(area, title, message, confirmText = 'OK', cancelText = 'Cancel') {
            dialogShown(area, title, message);
            return confirmBox(title, message, confirmText, cancelText).then((ok) => { dialogAnswered(area, title, ok ? confirmText : cancelText); return ok; });
        }
        function showChoiceDialog(area, title, message, choices) {
            dialogShown(area, title, message);
            return choiceBox(title, message, choices).then((v) => {
                dialogAnswered(area, title, v == null ? 'closed' : ((choices || []).find(c => c.value === v) || {}).label || String(v));
                return v;
            });
        }
        function showInputDialog(area, title, message, defaultValue = '', placeholder = '', confirmText = 'OK', cancelText = 'Cancel') {
            dialogShown(area, title, message);
            return inputBox(title, message, defaultValue, placeholder, confirmText, cancelText).then((v) => {
                dialogAnswered(area, title, v == null ? cancelText : `${confirmText} ("${v}")`);
                return v;
            });
        }
        function showDeleteWarningDialog(purchasedCount) {
            dialogShown('MOVE', 'Owned books', `deleting ${purchasedCount} purchased book(s)`);
            return deleteWarningBox(purchasedCount).then((v) => { dialogAnswered('MOVE', 'Owned books', v === 'delete' ? 'Delete Anyway' : 'Cancel'); return v; });
        }

        function infoBox(title, message) {
            return new Promise((resolve) => {
                const overlay = document.createElement('div');
                overlay.className = 'rw-imperative-overlay'; // v7.10.1-alpha.6 - counts as an open dialog (see imperativeDialogsUp)
                overlay.style.cssText = `
                    position: fixed; top: 0; left: 0; right: 0; bottom: 0;
                    background: rgba(0, 0, 0, 0.5);
                    display: flex; align-items: center; justify-content: center;
                    z-index: 10000;
                `;

                const dialog = document.createElement('div');
                dialog.style.cssText = `
                    background: var(--bg-surface); border-radius: 8px; padding: 24px;
                    max-width: 600px; width: 90%; max-height: 80vh; overflow-y: auto;
                    box-shadow: var(--shadow-modal);
                    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
                `;

                const titleEl = document.createElement('h2');
                titleEl.textContent = title;
                titleEl.style.cssText = `margin: 0 0 16px 0; font-size: 20px; font-weight: 600; color: var(--text-primary);`;

                const messageEl = document.createElement('div');
                messageEl.style.cssText = `margin-bottom: 24px; font-size: 14px; line-height: 1.6; color: var(--text-secondary); white-space: pre-line;`;
                messageEl.textContent = message;
                markDialogText(titleEl, messageEl); // v7.19.0-alpha.4

                const button = document.createElement('button');
                button.textContent = 'OK';
                button.style.cssText = `
                    background: var(--bg-accent); color: var(--text-on-accent); border: none;
                    border-radius: 4px; padding: 10px 24px; font-size: 14px; font-weight: 500; cursor: pointer; float: right;
                `;
                button.onmouseover = () => button.style.background = 'var(--bg-accent-hover)';
                button.onmouseout = () => button.style.background = 'var(--bg-accent)';
                // v7.10.1-alpha.9 - Esc + ✕ dismiss (shared chrome)
                const close = attachDialogDismiss(overlay, dialog, () => { if (overlay.parentNode) document.body.removeChild(overlay); resolve(); }, undefined);
                button.onclick = () => close();

                dialog.appendChild(titleEl);
                dialog.appendChild(messageEl);
                dialog.appendChild(button);
                overlay.appendChild(dialog);
                document.body.appendChild(overlay);
            });
        }

        // v6.0.0-alpha.45: Progress dialog for relay import (mutable content, no button initially)
        // Returns controller: { update(msg), finish(title, msg), close() }
        function progressBox(title, message) {
            const overlay = document.createElement('div');
            overlay.className = 'rw-imperative-overlay'; // v7.10.1-alpha.6 - counts as an open dialog (see imperativeDialogsUp)
            overlay.style.cssText = `
                position: fixed; top: 0; left: 0; right: 0; bottom: 0;
                background: rgba(0, 0, 0, 0.5);
                display: flex; align-items: center; justify-content: center;
                z-index: 10000;
            `;

            const dialog = document.createElement('div');
            dialog.style.cssText = `
                background: var(--bg-surface); border-radius: 8px; padding: 24px;
                max-width: 600px; width: 90%; max-height: 80vh; overflow-y: auto;
                box-shadow: var(--shadow-modal);
                font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            `;

            const titleEl = document.createElement('h2');
            titleEl.textContent = title;
            titleEl.style.cssText = `margin: 0 0 16px 0; font-size: 20px; font-weight: 600; color: var(--text-primary);`;

            const messageEl = document.createElement('div');
            messageEl.style.cssText = `margin-bottom: 24px; font-size: 14px; line-height: 1.6; color: var(--text-secondary); white-space: pre-line;`;
            messageEl.textContent = message;
            markDialogText(titleEl, messageEl); // v7.19.0-alpha.4

            const buttonContainer = document.createElement('div');
            buttonContainer.style.cssText = `text-align: right;`;

            // v7.4.0 - Indeterminate motion bar: long phases with a static dialog read as hung
            if (!document.getElementById('rw-progress-anim')) {
                const st = document.createElement('style');
                st.id = 'rw-progress-anim';
                st.textContent = '@keyframes rwProgressSlide { 0% { left: -35%; } 100% { left: 100%; } }';
                document.head.appendChild(st);
            }
            const barTrack = document.createElement('div');
            barTrack.style.cssText = 'position:relative; height:6px; border-radius:3px; overflow:hidden; background: var(--border-default, #e2e8f0); margin-bottom: 20px;';
            const barFill = document.createElement('div');
            barFill.style.cssText = 'position:absolute; top:0; height:100%; width:35%; border-radius:3px; background: var(--bg-accent, #4f46e5); animation: rwProgressSlide 1.2s ease-in-out infinite;';
            barTrack.appendChild(barFill);

            dialog.appendChild(titleEl);
            dialog.appendChild(messageEl);
            dialog.appendChild(barTrack);
            dialog.appendChild(buttonContainer);
            overlay.appendChild(dialog);
            document.body.appendChild(overlay);

            // v7.18.0-alpha.68 - a layer in the one overlay stack (key + undo fence, correct stacking). Esc does NOTHING while
            // the work runs (a running import must not be Esc-dismissed — the long-standing rule); once finish() shows OK,
            // Esc acts as OK. `remove` is the single exit: drops the layer and the overlay (idempotent).
            let onEscAfterFinish = null;
            const layerId = overlayRegistry.pushLayer({ close: () => { if (onEscAfterFinish) onEscAfterFinish(); }, kind: 'modal', nodeRef: { current: dialog }, detached: true }); // alpha.69 - see attachDialogDismiss
            const remove = () => { overlayRegistry.removeLayer(layerId); if (overlay.parentNode) document.body.removeChild(overlay); };
            onBackdropClick(overlay, layerId, () => { if (onEscAfterFinish) onEscAfterFinish(); }); // alpha.70 - like Esc: nothing while running, OK after

            return {
                update(msg) {
                    messageEl.textContent = msg;
                },
                // v7.19.0-alpha.6/11 - optional extras = [{ key, label }]: buttons left of OK (e.g. "Clear 2 goals", "Review…").
                // Resolves with the clicked one's key, else undefined (OK / Esc / background — unchanged for every existing caller).
                finish(newTitle, msg, extras) {
                    return new Promise((resolve) => {
                        titleEl.textContent = newTitle;
                        messageEl.textContent = msg;
                        barTrack.style.display = 'none';
                        const button = document.createElement('button');
                        button.textContent = 'OK';
                        button.style.cssText = `
                            background: var(--bg-accent); color: var(--text-on-accent); border: none;
                            border-radius: 4px; padding: 10px 24px; font-size: 14px; font-weight: 500; cursor: pointer;
                        `;
                        button.onmouseover = () => button.style.background = 'var(--bg-accent-hover)';
                        button.onmouseout = () => button.style.background = 'var(--bg-accent)';
                        const ok = () => { remove(); resolve(); };
                        button.onclick = ok;
                        onEscAfterFinish = ok; // from here on, Esc = OK
                        (extras || []).forEach(({ key, label }) => {
                            const xb = document.createElement('button');
                            xb.textContent = label;
                            xb.style.cssText = `
                                background: var(--bg-elevated); color: var(--text-primary); border: 1px solid var(--border-strong);
                                border-radius: 4px; padding: 10px 18px; font-size: 14px; cursor: pointer; margin-right: 8px;
                            `;
                            xb.onclick = () => { remove(); resolve(key); };
                            buttonContainer.appendChild(xb);
                        });
                        buttonContainer.appendChild(button);
                        button.focus();
                    });
                },
                close() {
                    remove();
                }
            };
        }

