                                    borderRadius: '4px',
                                    background: tagFilter.length > 0 ? 'var(--bg-selected)' : 'var(--bg-surface)',
                                    color: tagFilter.length > 0 ? 'var(--text-accent-strong)' : 'var(--text-secondary)',
                                    cursor: 'pointer',
